  1	// Package webhook delivers payment events to merchant endpoints with signed
  2	// payloads, retries with exponential backoff and a dead-letter list.
  3	package webhook
  4	
  5	import (
  6		"context"
  7		"encoding/json"
  8		"fmt"
  9		"net/http"
 10		"sync"
 11		"time"
 12	
 13		"example.com/gopayments/clock"
 14		"example.com/gopayments/payment"
 15	)
 16	
 17	// Event is the webhook payload.
 18	type Event struct {
 19		ID         string          `json:"id"`
 20		Type       string          `json:"type"`
 21		MerchantID string          `json:"merchant_id"`
 22		CreatedAt  time.Time       `json:"created_at"`
 23		Data       json.RawMessage `json:"data"`
 24	}
 25	
 26	// Endpoint is a merchant's webhook destination.
 27	type Endpoint struct {
 28		URL    string
 29		Secret string
 30	}
 31	
 32	// Endpoints resolves the endpoint of a merchant.
 33	type Endpoints interface {
 34		Endpoint(merchantID string) (Endpoint, bool)
 35	}
 36	
 37	// StaticEndpoints is a fixed merchant -> endpoint map.
 38	type StaticEndpoints map[string]Endpoint
 39	
 40	// Endpoint implements Endpoints.
 41	func (s StaticEndpoints) Endpoint(merchantID string) (Endpoint, bool) {
 42		e, ok := s[merchantID]
 43		return e, ok
 44	}
 45	
 46	// Policy controls retries.
 47	type Policy struct {
 48		MaxAttempts int
 49		BaseDelay   time.Duration
 50		MaxDelay    time.Duration
 51	}
 52	
 53	// DefaultPolicy is the production retry policy.
 54	func DefaultPolicy() Policy {
 55		return Policy{MaxAttempts: 6, BaseDelay: time.Second, MaxDelay: 10 * time.Minute}
 56	}
 57	
 58	// Backoff is the wait after failed attempt n (n >= 1): BaseDelay * 2^(n-1),
 59	// capped at MaxDelay.
 60	func (p Policy) Backoff(n int) time.Duration {
 61		d := p.BaseDelay << (n - 1)
 62		if d > p.MaxDelay {
 63			return p.MaxDelay
 64		}
 65		return d
 66	}
 67	
 68	// DeadLetter is an event that exhausted its retries or failed permanently.
 69	type DeadLetter struct {
 70		Event      Event
 71		Attempts   int
 72		LastStatus int
 73		LastError  string
 74		FailedAt   time.Time
 75	}
 76	
 77	// Dispatcher queues events and delivers them.
 78	type Dispatcher struct {
 79		sender    Sender
 80		endpoints Endpoints
 81		clock     clock.Clock
 82		policy    Policy
 83	
 84		mu        sync.Mutex
 85		seq       int
 86		queue     []Event
 87		dead      []DeadLetter
 88		delivered int
 89	}
 90	
 91	var _ payment.Publisher = (*Dispatcher)(nil)
 92	
 93	// NewDispatcher wires a dispatcher.
 94	func NewDispatcher(sender Sender, endpoints Endpoints, clk clock.Clock, policy Policy) *Dispatcher {
 95		return &Dispatcher{sender: sender, endpoints: endpoints, clock: clk, policy: policy}
 96	}
 97	
 98	type paymentData struct {
 99		PaymentID string `json:"payment_id"`
100		Status    string `json:"status"`
101		Amount    string `json:"amount"`
102		Currency  string `json:"currency"`
103		Refunded  string `json:"refunded_amount"`
104		RefundID  string `json:"refund_id,omitempty"`
105	}
106	
107	// Publish implements payment.Publisher by queueing a webhook event.
108	func (d *Dispatcher) Publish(_ context.Context, ev payment.Event) error {
109		data := paymentData{
110			PaymentID: ev.Payment.ID,
111			Status:    string(ev.Payment.Status),
112			Amount:    ev.Payment.Amount.Decimal(),
113			Currency:  ev.Payment.Amount.Currency.Code,
114			Refunded:  ev.Payment.RefundedAmount().Decimal(),
115		}
116		if ev.Refund != nil {
117			data.RefundID = ev.Refund.ID
118		}
119		raw, err := json.Marshal(data)
120		if err != nil {
121			return fmt.Errorf("encode %s event: %w", ev.Type, err)
122		}
123		d.mu.Lock()
124		defer d.mu.Unlock()
125		d.seq++
126		d.queue = append(d.queue, Event{
127			ID:         fmt.Sprintf("evt_%06d", d.seq),
128			Type:       ev.Type,
129			MerchantID: ev.Payment.MerchantID,
130			CreatedAt:  d.clock.Now(),
131			Data:       raw,
132		})
133		return nil
134	}
135	
136	// Pending returns the number of queued, undelivered events.
137	func (d *Dispatcher) Pending() int {
138		d.mu.Lock()
139		defer d.mu.Unlock()
140		return len(d.queue)
141	}
142	
143	// Delivered returns how many events were delivered successfully.
144	func (d *Dispatcher) Delivered() int {
145		d.mu.Lock()
146		defer d.mu.Unlock()
147		return d.delivered
148	}
149	
150	// DeadLetters returns a snapshot of the dead-letter list.
151	func (d *Dispatcher) DeadLetters() []DeadLetter {
152		d.mu.Lock()
153		defer d.mu.Unlock()
154		return append([]DeadLetter(nil), d.dead...)
155	}
156	
157	// Flush delivers every queued event. It returns early only if ctx is done;
158	// undelivered events stay queued in that case.
159	func (d *Dispatcher) Flush(ctx context.Context) error {
160		d.mu.Lock()
161		batch := d.queue
162		d.queue = nil
163		d.mu.Unlock()
164	
165		for i, ev := range batch {
166			if err := d.deliver(ctx, ev); err != nil {
167				d.mu.Lock()
168				d.queue = append(append([]Event(nil), batch[i:]...), d.queue...)
169				d.mu.Unlock()
170				return fmt.Errorf("flush webhooks: %w", err)
171			}
172		}
173		return nil
174	}
175	
176	// deliver attempts ev until success, a permanent failure or MaxAttempts.
177	// It only returns an error when ctx is done.
178	func (d *Dispatcher) deliver(ctx context.Context, ev Event) error {
179		ep, ok := d.endpoints.Endpoint(ev.MerchantID)
180		if !ok {
181			return nil // merchant has no webhook configured
182		}
183		body, err := json.Marshal(ev)
184		if err != nil {
185			d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
186			return nil
187		}
188		var (
189			status  int
190			sendErr error
191			attempt int
192		)
193		for attempt = 1; attempt <= d.policy.MaxAttempts; attempt++ {
194			headers := map[string]string{
195				"Content-Type":  "application/json",
196				"Webhook-Id":    ev.ID,
197				SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
198			}
199			status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
200			if sendErr == nil && status >= 200 && status < 300 {
201				d.mu.Lock()
202				d.delivered++
203				d.mu.Unlock()
204				return nil
205			}
206			if !retryable(status, sendErr) || attempt == d.policy.MaxAttempts {
207				break
208			}
209			if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
210				return err
211			}
212		}
213		d.deadLetter(ev, attempt, status, sendErr)
214		return nil
215	}
216	
217	func (d *Dispatcher) deadLetter(ev Event, attempts, status int, err error) {
218		dl := DeadLetter{Event: ev, Attempts: attempts, LastStatus: status, FailedAt: d.clock.Now()}
219		if err != nil {
220			dl.LastError = err.Error()
221		}
222		d.mu.Lock()
223		defer d.mu.Unlock()
224		d.dead = append(d.dead, dl)
225	}
226	
227	// retryable reports whether a failed attempt should be retried: transport
228	// errors, 408, 429 and 5xx are transient; any other status is permanent.
229	func retryable(status int, err error) bool {
230		if err != nil {
231			return true
232		}
233		return status == http.StatusRequestTimeout || status == http.StatusTooManyRequests || status >= 500
234	}

