 17	// scriptedSender returns the scripted outcomes in order, then 200.
 18	type scriptedSender struct {
 19		mu       sync.Mutex
 20		statuses []int
 21		errs     []error
 22		calls    []Delivery
 23	}
 24	
 25	func (s *scriptedSender) Send(_ context.Context, d Delivery) (int, error) {
 26		s.mu.Lock()
 27		defer s.mu.Unlock()
 28		i := len(s.calls)
 29		s.calls = append(s.calls, d)
 30		if i < len(s.statuses) {
 31			var err error
 32			if i < len(s.errs) {
 33				err = s.errs[i]
 34			}
 35			return s.statuses[i], err
 36		}
 37		return http.StatusOK, nil
 38	}
