// Backoff is the wait after failed attempt n (n >= 1): BaseDelay * 2^(n-1),
// capped at MaxDelay.
func (p Policy) Backoff(n int) time.Duration {
	if p.BaseDelay <= 0 || p.MaxDelay <= 0 {
		return 0
	}
	if n <= 1 {
		n = 1
	}
	shift := n - 1
	if shift >= 63 || p.BaseDelay > p.MaxDelay>>shift {
		return p.MaxDelay
	}
	return p.BaseDelay << shift
}

