func TestBackoffNoOverflowAndMonotonic(t *testing.T) {
	policies := []Policy{
		{MaxAttempts: 48, BaseDelay: time.Second, MaxDelay: time.Hour},
		{MaxAttempts: 100, BaseDelay: time.Millisecond, MaxDelay: 24 * time.Hour},
		{MaxAttempts: 100, BaseDelay: time.Nanosecond, MaxDelay: time.Duration(math.MaxInt64)},
		{MaxAttempts: 10, BaseDelay: 3 * time.Nanosecond, MaxDelay: 5 * time.Nanosecond},
		{MaxAttempts: 10, BaseDelay: 10 * time.Second, MaxDelay: 5 * time.Second},
		{MaxAttempts: 10, BaseDelay: time.Duration(math.MaxInt64), MaxDelay: time.Duration(math.MaxInt64)},
	}
	attempts := []int{math.MinInt, -10, -1, 0}
	for n := 1; n <= 128; n++ {
		attempts = append(attempts, n)
	}
	attempts = append(attempts, 1_000, 1_000_000, math.MaxInt)

	for _, p := range policies {
		var prev time.Duration
		for _, n := range attempts {
			got := p.Backoff(n)
			if got <= 0 {
				t.Fatalf("policy %+v Backoff(%d) = %v, want > 0", p, n, got)
			}
			if got > p.MaxDelay {
				t.Fatalf("policy %+v Backoff(%d) = %v, exceeds MaxDelay %v", p, n, got, p.MaxDelay)
			}
			if got < prev {
				t.Fatalf("policy %+v Backoff(%d) = %v < previous %v", p, n, got, prev)
			}
			prev = got
		}
	}

	if got := (Policy{}).Backoff(1); got != 0 {
		t.Fatalf("zero Policy Backoff(1) = %v, want 0", got)
	}
}

func TestDeliverEnterpriseMaxAttemptsBackoff(t *testing.T) {
	const maxAttempts = 48
	statuses := make([]int, maxAttempts)
	for i := range statuses {
		statuses[i] = http.StatusServiceUnavailable
	}
	s := &scriptedSender{statuses: statuses}
	clk := clock.NewFake(time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC))
	eps := StaticEndpoints{"m_ent": {URL: "https://ent.example/hooks", Secret: "s3cret"}}
	d := NewDispatcher(s, eps, clk, Policy{MaxAttempts: maxAttempts, BaseDelay: time.Second, MaxDelay: time.Hour})

	publishOne(t, d, "m_ent")
	if err := d.Flush(context.Background()); err != nil {
		t.Fatal(err)
	}
	if len(s.calls) != maxAttempts {
		t.Fatalf("calls = %d, want %d", len(s.calls), maxAttempts)
	}
	sleeps := clk.Sleeps()
	if len(sleeps) != maxAttempts-1 {
		t.Fatalf("sleeps = %d, want %d", len(sleeps), maxAttempts-1)
	}
	for i, w := range sleeps {
		n := i + 1
		want := time.Duration(1<<(n-1)) * time.Second
		if n > 12 {
			want = time.Hour
		}
		if w != want {
			t.Fatalf("sleep after attempt %d = %s, want %s", n, w, want)
		}
	}
	dead := d.DeadLetters()
	if len(dead) != 1 || dead[0].Attempts != maxAttempts || dead[0].LastStatus != http.StatusServiceUnavailable {
		t.Fatalf("dead letters = %+v", dead)
	}
}

